"use strict";
let age = 20;
console.log(age);
//integer
let marks = 90;
console.log(marks);
//float
let percentage = 90.9;
console.log(percentage);
//exponential
let salary = 9e3;
console.log(salary);
//negative number
let salary1 = -900;
console.log(salary1);
// NaN
let result = NaN;
console.log(result);
let result1 = 0 / 0;
console.log(result1);
// infinity
let data = 10 / 0;
console.log(data);
//addition
let a = 10;
let b = 20;
let c = a + b;
console.log(c);
//subtraction
let a1 = 10;
let b1 = 20;
let c1 = a1 - b1;
console.log(c1);
//multiplication
let a2 = 10;
let b2 = 20;
let c2 = a2 * b2;
console.log(c2);
//division
let a3 = 10;
let b3 = 20;
let c3 = a3 / b3;
console.log(c3);
//modulus
let a4 = 10;
let b4 = 20;
let c4 = a4 % b4;
console.log(c4);
